const source = $input.first().json;
const body = source.body ?? source;
if (!body.lead_id || !body.event || !body.contact || !body.answers) throw new Error('Payload EPIC inválido');
const a = body.answers;
let score = 0;
const capital = {'Acima de US$ 100 mil':40,'US$ 30 mil a US$ 100 mil':30,'US$ 15 mil a US$ 30 mil':20};
const prazo = {'Neste mês':25,'Em 30 a 60 dias':15};
score += capital[a.epic_capital_90d] ?? 0;
score += prazo[a.epic_prazo_aporte] ?? 0;
if (Number(a.epic_prioridade_0a10) >= 8) score += 20;
if (a.epic_liquidez === 'Parado em conta / CDI') score += 10;
if (Array.isArray(a.epic_estrutura_us) && a.epic_estrutura_us.some(v => v !== 'Nenhuma ainda')) score += 5;
score = Math.max(0, Math.min(100, score));
const complete = body.event === 'quiz_concluido';
const hardGate = a.epic_capital_90d === 'Menos de US$ 15 mil (ainda montando)' || a.epic_momento === 'Ainda estou estudando. Não pretendo alocar capital nos próximos 6 meses.';
let route = 'in_progress', tag = 'em_qualificacao', duration = '', reason = 'Jornada ainda não concluída.';
if (complete && hardGate) { route='nutrition'; tag='nao_qualificado'; reason='Sem ticket mínimo ou sem intenção de aporte nos próximos 6 meses.'; }
else if (complete && score < 40) { route='nutrition'; tag='nutricao_score'; reason='Score abaixo de 40 pontos; segue para maturação antes da agenda.'; }
else if (complete && a.epic_momento?.startsWith('Tenho US$ 100 mil')) { route='strategic_45'; tag='estrategico'; duration=45; reason='Lead estratégico elegível para agenda prioritária de 45 minutos.'; }
else if (complete && a.epic_momento?.startsWith('Tenho US$ 30 mil')) { route='calendar_45'; tag='qualificado_alto'; duration=45; reason='Lead qualificado para agenda de 45 minutos.'; }
else if (complete) { route='calendar_30'; tag='qualificado_entrada'; duration=30; reason='Lead qualificado para agenda de entrada de 30 minutos.'; }
const temperature = route === 'nutrition' ? 'frio' : score >= 70 ? 'quente' : score >= 40 ? 'morno' : 'frio';
const t = body.tracking ?? {};
const row = {
  lead_id: body.lead_id, created_at: body.client_started_at, updated_at: body.occurred_at,
  last_event_id: body.event_id, last_event: body.event, current_stage: body.stage, current_screen: body.screen, progress_percent: body.progress_percent,
  nome: body.contact.nome ?? '', whatsapp: body.contact.whatsapp ?? '', email: body.contact.email ?? '',
  epic_perfil: a.epic_perfil ?? '', epic_estrutura_us: Array.isArray(a.epic_estrutura_us) ? a.epic_estrutura_us.join(' | ') : '',
  epic_experiencia_exterior: a.epic_experiencia_exterior ?? '', epic_objecao_principal: a.epic_objecao_principal ?? '',
  epic_capital_90d: a.epic_capital_90d ?? '', epic_liquidez: a.epic_liquidez ?? '', epic_expectativa_retorno: a.epic_expectativa_retorno ?? '',
  epic_motivador: a.epic_motivador ?? '', epic_prioridade_0a10: a.epic_prioridade_0a10 ?? '', epic_prazo_aporte: a.epic_prazo_aporte ?? '',
  epic_momento: a.epic_momento ?? '', epic_objecao_final: a.epic_objecao_final ?? '', epic_score: score, lead_temperature: temperature,
  route_key: route, tag, calendar_duration: duration, qualification_reason: reason, completed_at: complete ? body.occurred_at : '',
  utm_source: t.utm_source ?? '', utm_medium: t.utm_medium ?? '', utm_campaign: t.utm_campaign ?? '', utm_content: t.utm_content ?? '', utm_term: t.utm_term ?? '',
  fbclid: t.fbclid ?? '', gclid: t.gclid ?? '', creative_id: t.creative_id ?? '', landing_url: t.landing_url ?? '', referrer: t.referrer ?? '',
  calendar_event_id: '', meeting_start: '', meeting_end: '', meet_url: '', payload_json: JSON.stringify(body)
};
return [{json: row}];

const body = $input.first().json.body ?? $input.first().json;
const duration = [30,45].includes(Number(body.duration)) ? Number(body.duration) : 30;
const days = Math.max(1, Math.min(31, Number(body.days) || 21));
const now = new Date();
const timeMin = new Date(now.getTime() + 24*60*60*1000);
const timeMax = new Date(now.getTime() + days*24*60*60*1000);
return [{json:{lead_id:body.lead_id,duration,days,timezone:'America/Sao_Paulo',timeMin:timeMin.toISOString(),timeMax:timeMax.toISOString()}}];

const request = $('Preparar janela').first().json;
const busy = $input.all().map(i => i.json).filter(i => i.start && i.end).map(i => ({start:new Date(i.start).getTime(),end:new Date(i.end).getTime()}));
const fmt = new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'});
const key = d => { const p=Object.fromEntries(fmt.formatToParts(d).map(x=>[x.type,x.value])); return `${p.year}-${p.month}-${p.day}`; };
const pad = n => String(n).padStart(2,'0');
const slots=[];
const now=Date.now();
for(let offset=1;offset<=request.days;offset++){
  const probe=new Date(now+offset*86400000);
  const date=key(probe);
  const noon=new Date(`${date}T12:00:00-03:00`);
  const weekday=noon.getUTCDay();
  if(weekday===0||weekday===6) continue;
  for(let minute=9*60;minute+request.duration<=18*60;minute+=30){
    const hh=pad(Math.floor(minute/60)), mm=pad(minute%60);
    const start=new Date(`${date}T${hh}:${mm}:00-03:00`);
    const end=new Date(start.getTime()+request.duration*60000);
    if(start.getTime()<now+24*60*60*1000) continue;
    if(busy.some(b=>start.getTime()<b.end && end.getTime()>b.start)) continue;
    slots.push({start:start.toISOString(),end:end.toISOString()});
  }
}
return [{json:{ok:true,timezone:'America/Sao_Paulo',duration:request.duration,slots:slots.slice(0,80)}}];

const lead=$input.first().json;
const request=$('Webhook — Agendar').first().json.body;
if(!lead.lead_id) throw new Error('Lead não encontrado');
if(lead.route_key==='nutrition'||Number(lead.epic_score)<40) throw new Error('Lead não elegível para agenda');
const duration=Number(lead.calendar_duration);
if(![30,45].includes(duration)) throw new Error('Duração de agenda inválida');
const start=new Date(request.start);
if(Number.isNaN(start.getTime())||start.getTime()<Date.now()+60*60*1000) throw new Error('Horário inválido');
const end=new Date(start.getTime()+duration*60000);
return [{json:{...lead,start:start.toISOString(),end:end.toISOString(),calendar_duration:duration}}];

